ek-ai/cordis\": \"^4.0.1 || ^4.0.6-alpha.1\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"^0.1.0-rc.7 || ^0.1.1-rc.1 || ^0.1.2-alpha.1 || ^0.1.5-rc.1 || ^0.2.0-rc.2 || ^0.2.2-alpha.2\",\n    \"react\": \"^18.2.0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/dsh-client-ui-primitives\": {\n      \"optional\": true\n    }\n  },\n  \"license\": \"MIT\",\n  \"dependencies\": {\n    \"js-yaml\": \"4.3.2\"\n  }\n}\n"
