e.copyLabel), so a message with\n\t\t// a fenced block threw when only the old flat `codeLabels` prop was passed\n\t\t// (issue #3). Build the nested shape, and hand its code half to the old prop too,\n\t\t// so one build serves both the 0.1.1-rc and the 0.1.2+ platforms. The objects are\n\t\t// cached per UI_TEXT dictionary because MarkdownText is memoized: a fresh identity\n\t\t// on every render would silently defeat that memo.\n\t\tvar mdLabelsCache = typeof WeakMap === \"function\" ? new WeakMap() : null;\n\t\tfunction markdownLabels(tt) {\n\t\t\tif (!tt) return undefined;\n\t\t\tif (mdLabelsCache) {\n\t\t\t\tvar cached = mdLabelsCache.get(tt);\n\t\t\t\tif (cached) return cached;\n\t\t\t}\n\t\t\tvar labels = {\n\t\t\t\tcode: { copyLabel: tt.copy, copiedLabel: tt.copied },\n\t\t\t\tfootnotes: tt.footnotes || \"Footnotes\",\n\t\t\t};\n\t\t\tif (mdLabelsCache) mdLabelsCache.set(tt, labels);\n\t\t\treturn labels;\n\t\t}\n\t\tvar IconChecklist = primitives && primitives.IconChecklistOutline14 ? primitives.IconChecklistOutline14 : null;\n\t\tvar IconChevronUp = primitives && primitives.IconChevronUpOutline14 ? primitives.IconChevronUpOutline14 : null;\n\t\tvar IconChevronDown = primitives && primitives.IconChevronDownOutline14 ? primitives.IconChevronDownOutline14 : null;\n\t\tvar createElement = function (type, props) {\n\t\t\tvar children = [];\n\t\t\tfor (var i = 2; i < arguments.length; i++) children.push(arguments[i]);\n\t\t\treturn React.createElement.apply(React, [type, props].concat(children));\n\t\t};\n\t\tvar Fragment = React.Fragment;\n\t\tvar useState = React.useState;\n\t\tvar useEffect = React.useEffect;\n\t\tvar useId = React.useId;\n\t\tvar Component = React.Component;\n\n\t\t// ------------------------------------------------------------------\n\t\t// stylesheet (data-plugin-css pattern, same as shipped client bundles)\n\t\t// ------------------------------------------------------------------\n\t\tvar CSS_TEXT = [\n\t\t\t\".xl-think{margin:2px 0}\",\