that touch (<nav>) content or add a nav, so the steady-state\n\t\t\t// cost while messages stream is a few cheap record checks, and the scan\n\t\t\t// itself is debounced.\n\t\t\trecordSlot(\"settingsGlyph\", function () {\n\t\t\t\t// documentElement rather than body: the bundle is loaded \"immediately\",\n\t\t\t\t// so <body> may not exist yet, while the root element always does.\n\t\t\t\tif (typeof document === \"undefined\" || !document.documentElement ||\n\t\t\t\t\ttypeof MutationObserver !== \"function\") return undefined;\n\t\t\t\tvar pending = null;\n\t\t\t\tvar schedule = function () {\n\t\t\t\t\tif (pending !== null) return;\n\t\t\t\t\tpending = setTimeout(function () { pending = null; decorateSettingsGlyph(); }, 150);\n\t\t\t\t};\n\t\t\t\tvar touchesNav = function (records) {\n\t\t\t\t\tfor (var i = 0; i < records.length; i++) {\n\t\t\t\t\t\tvar r = records[i];\n\t\t\t\t\t\tif (r.target && r.target.closest && r.target.closest(\"nav\")) return true;\n\t\t\t\t\t\tvar added = r.addedNodes || [];\n\t\t\t\t\t\tfor (var k = 0; k < added.length; k++) {\n\t\t\t\t\t\t\tvar n = added[k];\n\t\t\t\t\t\t\tif (n && n.nodeType === 1 && (n.tagName === \"NAV\" || (n.querySelector && n.querySelector(\"nav\")))) return true;\n\t\t\t\t\t\t}\n\t\t\t\t\t}\n\t\t\t\t\treturn false;\n\t\t\t\t};\n\t\t\t\tvar observer = new MutationObserver(function (records) { if (touchesNav(records)) schedule(); });\n\t\t\t\tobserver.observe(document.documentElement, { childList: true, subtree: true });\n\t\t\t\tschedule();\n\t\t\t\tvar dispose = function () {\n\t\t\t\t\tif (pending !== null) clearTimeout(pending);\n\t\t\t\t\tobserver.disconnect();\n\t\t\t\t\tundecorateSettingsGlyph();\n\t\t\t\t};\n\t\t\t\t// recordSlot's return value is dropped, so hand the cleanup to Cordis\n\t\t\t\t// as well: that is what runs when the plugin is disposed. Best effort —\n\t\t\t\t// a runtime without ctx.effect must not break apply().\n\t\t\t\ttry { if (typeof ctx.effect === \"function\") ctx.effect(function () 