      "path": "lib/index.js",
      "content": "// dsh-think-translate host half: same-origin translation proxy with a pluggable\n// provider chain. The browser calls POST /_xlate/translate (no CORS involved);\n// this side owns provider adapters, DSH credential references, caching,\n// and the system-proxy-aware native transport.\n//\n// Providers: google (gtx), bing (ttranslatev3), openai-compatible (any\n// /chat/completions endpoint — usually the local Ollama).\nimport { readFile, writeFile, mkdir, copyFile, access, unlink, stat, rename } from 'node:fs/promises'\nimport { dirname, join } from 'node:path'\nimport { tmpdir } from 'node:os'\nimport { randomUUID } from 'node:crypto'\nimport { createLocalPreparation, ollamaOrigin, validOllamaSignature } from './ollama.js'\nimport { createLocalModelLifecycle, modelKeepAlive } from './local-model.js'\nimport { fileURLToPath } from 'node:url'\nimport { requestTextInfo, isLoopback, DEFAULT_HEADERS } from './transport.js'\nimport { scanDshProviders, extractDshProviders, extractCredRefs, extractHarnessDefaultRoute } from './discovery.js'\nimport { protectedTextParts, translateProtectedText } from './text.js'\nimport { prepareCredentials, discardCredentials, applyCredentialEdits, ownedCredentialRefs } from './credentials.js'\nimport { translationNamespace, officialTranslationState } from './runtime-state.js'\nimport { normalizeGlossaryPatch, glossaryEntriesForTarget, translateWithGlossary, splitGlossaryText } from './glossary.js'\nimport { BUILTIN_GLOSSARY } from './glossary-presets.js'\n\nexport const name = 'dsh-think-translate'\n\n// Hard dependencies: without this declaration apply() ran before the web\n// server row mounted, ctx.get('webServer') returned undefined, and the whole\n// plugin silently registered nothing (no error, no routes).\nexport const inject = ['webServer', 'subprocess', 'timer']\n\nconst CONFIG_PATH = fileURLToPath(new URL('./config.json', import.meta.url))\nconst PACKAGE_PATH = fileURLToPath(new URL('../package.json', import.meta.url))\n\n// Fallback locations for launchers without profileContext. Modern launchers\n// supply the active profile and home directly; discovery.js gives them priority.\nfunction harnessHomeCandidates() {\n  const out = []\n  const env = process.env.DSH_HOME\n  if (typeof env === 'string' && env.trim()) out.push(env.trim())\n  const home = process.env.HOME || process.env.USERPROFILE || ''\n  if (home) {\n    out.push(home.replace(/[\\\\/]+$/, '') + '/.dsh')\n    if (process.platform === 'darwin') out.push(home.replace(/[\\\\/]+$/, '') + '/Library/Application Support/dsh-desktop/harness')\n  }\n  if (process.env.APPDATA) out.push(process.env.APPDATA.replace(/[\\\\/]+$/, '') + '\\\\dsh-desktop\\\\harness')\n  return out\n}\n\n// The first candidate holding a settings.yaml, else the first candidate at all\n// (so the diagnostic can say which one was looked at).\nfunction pickHarnessHome(candidates, exists) {\n  for (const dir of candidates) {\n    try { if (exists(dir + '/settings.yaml')) return { home: dir, settingsFound: true } } catch (e) { /* keep looking */ }\n  }\n  return { home: candidates[0] || '', settingsFound: false }\n}\n\n// Diagnostic for the settings panel: which home was used and what was read there.\nlet dshScanDiag = { home: null, settingsFound: false, credsFound: false, providers: [] }\n\n// Defaults: local model (Ollama) enabled from the start — the chain is\n// fail-open, so if Ollama is down it falls back to google/bing. `chain` is the\n// ordered provider list for translation; disabled providers are silently\n// skipped. `fallback` is an independent backup chain tried when the main chain\n// fails entirely.\nconst DEFAULT_CONFIG = {\n  glossary: { enabled: true, builtin: false, entries: {} },\n  localModel: { idleMinutes: 5 },\n  chain: ['google', 'bing', 'openai'],\n  // Legacy safety net, config-only since 2026-09-11: the settings UI no longer\n  // offers it (the chain itself ends with the free providers on a fresh install,\n  // and unchecking one is how you stop using it). Off by default so nothing runs\n  // behind the user's back.\n  fallback: { enabled: false, chain: ['google', 'bing'] },\n  providers: {\n    google: { type: 'google', enabled: true },\n    bing: { type: 'bing', enabled: true },\n    openai: { type: 'openai', enabled: true, baseURL: 'http://localhost:11434/v1', model: 'qwen2.5:7b-instruct', apiKey: 'ollama-local' },\n  },\n}\n\n// Valid provider types for the dynamic chain. Custom providers (user-added)\n// may be any of these; built-in google/bing are fixed.\nconst VALID_TYPES = ['google', 'bing', 'openai', 'anthropic']\n\n// ---------------------------------------------------------------- transport\n\nlet subprocessRef = null\nlet timerRef = null\nlet profileContextRef = null\nlet discoveryContextRef = null\nlet credentialRevision = 0\nlet configGeneration = 0\nlet configUpdates = Promise.resolve()\nfunction queueConfigChange(change) {\n  const task = configUpdates.then(change)\n  configUpdates = task.catch(() => {}) // A failed save must not block later edits.\n  return task\n}\n\n// Optional services may become active after this plugin's apply(). Resolve\n// them at each operation instead of retaining a startup-time absence.\nfunction credentialService() {\n  return discoveryContextRef?.get('credentials')\n}\n\nasync function localJson(url, options = {}, timeoutMs = 10000) {\n  const response = await fetch(url, { ...options, redirect: 'error', signal: AbortSignal.timeout(timeoutMs) })\n  const body = await response.json()\n  if (!response.ok || body.error) throw new Error(body.error || 'Ollama HTTP ' + response.status)\n  return body\n}\n\nasync function findOllamaExecutable() {\n  if (!subprocessRef) throw new Error('subprocess unavailable')\n  try { return await subprocessRef.resolveExecutable('ollama') } catch { /* Try installed-app locations when PATH is stale. */ }\n  const candidates = process.platform === 'win32'\n    ? [join(process.env.LOCALAPPDATA || '', 'Programs', 'Ollama', 'ollama.exe')]\n    : ['/usr/local/bin/ollama', '/usr/bin/ollama', '/Applications/Ollama.app/Contents/Resources/ollama']\n  if (process.platform === 'win32') for (const hive of ['HKCU', 'HKLM']) {\n    try {\n      const key = hive + ':\\\\Software\\\\Microsoft\\\\Windows\\\\CurrentVersion\\\\Uninstall\\\\{44E83376-CE68-45EB-8FC1-393500EB558C}_is1'\n      const result = await runProgram('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command',\n        '[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false);$p=Get-ItemProperty -LiteralPath ' + \"'\" + key + \"'\" + ' -ErrorAction Stop;[Console]::Write($p.InstallLocation)'], 8000)\n      if (result.trim()) candidates.push(join(result.trim(), 'ollama.exe'))\n    } catch { /* This hive may not contain an Ollama installation. */ }\n  }\n  for (const candidate of candidates) {\n    try { await access(candidate); return candidate } catch { /* Probe the next known installation location. */ }\n  }\n  return null\n}\n\nasync function startOllamaServer(executable, origin) {\n  const child = subprocessRef.spawn({\n    argv: [executable, 'serve'], cwd: await workdir(), graceMs: 2000,\n    stdio: { stdin: 'ignore', stdout: 'ignore', stderr: 'pipe' },\n    env: { OLLAMA_HOST: new URL(origin).host },\n  })\n  // Drain the long-lived pipe; the subprocess provider owns shutdown and joins.\n  if (child.stderr) (async () => { for await (const chunk of child.stderr) { void chunk } })().catch(() => {})\n  child.done.catch(() => {})\n}\n\nasync function streamModelPull(origin, model, progress) {\n  const response = await fetch(origin + '/api/pull', {\n    method: 'POST', headers: { 'Content-Type': 'application/json' }, redirect: 'error',\n    body: JSON.stringify({ model, stream: true }), signal: AbortSignal.timeout(60 * 60 * 1000),\n  })\n  if (!response.ok) throw new Error('Ollama download HTTP ' + response.status)\n  const decoder = new TextDecoder()\n  const layers = new Map()\n  let buffer = '', success = false\n  const consume = line => {\n    if (!line.trim()) return\n    const event = JSON.parse(line)\n    if (event.error) throw new Error(event.error)\n    if (event.digest && typeof event.total === 'number') layers.set(event.digest, {\n      total: event.total, completed: typeof event.completed === 'number' ? event.completed : 0,\n    })\n    let total = 0, completed = 0\n    for (const layer of layers.values()) { total += layer.total; completed += layer.completed }\n    progress({ total, completed, percent: total ? Math.min(100, Math.round(completed / total * 100)) : null })\n    if (event.status === 'success') success = true\n  }\n  for await (const bytes of response.body) {\n    buffer += decoder.decode(bytes, { stream: true })\n    let index\n    while ((index = buffer.indexOf('\\n')) >= 0) { consume(buffer.slice(0, index)); buffer = buffer.slice(index + 1) }\n  }\n  consume(buffer + decoder.decode())\n  if (!success) throw new Error('Model download ended before Ollama reported success')\n}\n\nasync function installOllama(progress) {\n  const file = join(tmpdir(), 'dsh-ollama-' + randomUUID() + '.exe')\n  try {\n    progress({ phase: 'downloading_ollama', percent: null, completed: 0, total: 0 })\n    let totalBytes = 0\n    try {\n      const headers = await runProgram('curl', await curlArgs(['--fail', '--head', '--location', 'https://ollama.com/download/OllamaSetup.exe']), 30000)\n      const lengths = [...headers.matchAll(/content-length:\\s*(\\d+)/gi)]\n      if (lengths.length) totalBytes = Number(lengths[lengths.length - 1][1])\n    } catch { /* A missing HEAD size does not prevent a signed download. */ }\n    const args = await curlArgs(['--fail', '--location', '--proto', '=https', '--proto-redir', '=https',\n      '--progress-bar', '--retry', '2', '--max-time', '1800', '--output', file, 'https://ollama.com/download/OllamaSetup.exe'])\n    // Replace curlArgs' silent/25-second prefix with the download's own limit.\n    const filtered = args.slice(3)\n    const executable = await subprocessRef.resolveExecutable('curl')\n    const child = subprocessRef.spawn({ argv: [executable, ...filtered], cwd: await workdir(), graceMs: 2000,\n      signal: AbortSignal.timeout(30 * 60 * 1000), stdio: { stdin: 'ignore', stdout: 'ignore', stderr: 'pipe' } })\n    let tail = ''\n    if (child.stderr) for await (const bytes of child.stderr) {\n      tail = (tail + new TextDecoder().decode(bytes)).slice(-2000)\n      const matches = [...tail.matchAll(/(\\d+(?:\\.\\d+)?)%/g)]\n      const downloaded = await stat(file).catch(() => null)\n      progress({ completed: downloaded ? downloaded.size : 0, total: totalBytes,\n        percent: matches.length ? Math.min(100, Number(matches[matches.length - 1][1])) : null })\n    }\n    const outcome = await child.done\n    if (outcome.exitCode !== 0) throw new Error('Ollama installer download failed: ' + tail.trim().slice(-300))\n    progress({ phase: 'verifying', percent: null })\n    const quoted = \"'\" + file.replace(/'/g, \"''\") + \"'\"\n    const signature = await runProgram('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command',\n      '$s=Get-AuthenticodeSignature -LiteralPath ' + quoted + '; @{status=[string]$s.Status;subject=$s.SignerCertificate.Subject}|ConvertTo-Json -Compress'], 30000)\n    if (!validOllamaSignature(JSON.parse(signature))) throw new Error('Ollama installer signature verification failed')\n    progress({ phase: 'installing', percent: null })\n    const appState = join(process.env.LOCALAPPDATA, 'Ollama')\n    await mkdir(appState, { recursive: true })\n    await writeFile(join(appState, 'upgraded'), '', 'utf8') // Official installer convention: launch the app hidden.\n    // The official per-user installer supports these unattended flags.\n    const controller = new AbortController()\n    const deadline = setTimeout(() => controller.abort(), 10 * 60 * 1000)\n    try {\n      // Ignore inherited pipes: a background app launched by the installer can\n      // retain them even after the installer itself exits successfully.\n      const child = subprocessRef.spawn({ argv: [file, '/VERYSILENT', '/NORESTART', '/SUPPRESSMSGBOXES'],\n        cwd: await workdir(), graceMs: 2000, signal: controller.signal,\n        stdio: { stdin: 'ignore', stdout: 'ignore', stderr: 'ignore' } })\n      const outcome = await child.done\n      if (outcome.exitCode !== 0) throw new Error('Ollama installation failed with exit code ' + outcome.exitCode)\n    } finally { clearTimeout(deadline) }\n  } finally {\n    await unlink(file).catch(() => {}) // Only this operation's unique installer download.\n  }\n}\n\nconst localPreparation = createLocalPreparation({\n  platform: process.platform, json: localJson, findExecutable: findOllamaExecutable,\n  startServer: startOllamaServer, install: installOllama, pull: streamModelPull,\n  wait: milliseconds => new Promise(resolve => setTimeout(resolve, milliseconds)),\n})\n\nconst localModels = createLocalModelLifecycle({ json: localJson, preparation: localPreparation })\n\nasync function viaLocalOllama(text, to, provider, policy) {\n  let response\n  try { response = await localJson(ollamaOrigin('openai', provider) + '/api/chat', {\n    method: 'POST', headers: { 'Content-Type': 'application/json' },\n    body: JSON.stringify({ model: provider.model, stream: false, keep_alive: modelKeepAlive(policy),\n      messages: [{ role: 'system', content: systemForTarget(to) }, { role: 'user', content: translationUserText(text) }] }),\n  }, 120000) } catch (error) {\n    if (error?.name === 'TimeoutError' || error?.name === 'AbortError') {\n      throw new Error('Ollama translation timed out after 120 seconds; the local model may be busy or too slow', { cause: error })\n    }\n    throw error\n  }\n  const translated = response.message?.content\n  if (typeof translated !== 'string' || !translated.trim()) throw new Error('Ollama returned an empty translation')\n  return translated\n}\n\nasync function workdir() {\n  return process.cwd() || '.'\n}\n\nasync function runProgram(exeName, args, timeoutMs) {\n  const sub = subprocessRef\n  if (!sub) throw new Error('subprocess unavailable')\n  const exe = await sub.resolveExecutable(exeName)\n  const child = sub.spawn({\n    argv: [exe].concat(args),\n    cwd: await workdir(),\n    stdio: { stdin: 'ignore', stdout: 'pipe', stderr: 'pipe' },\n    graceMs: 2000,\n  })\n  const readP = (async function () {\n    const chunks = []\n    if (child.stdout) {\n      for await (const c of child.stdout) chunks.push(c)\n    }\n    return chunks\n  })()\n  // stderr is drained even though only stdout carries the payload: an unread pipe\n  // blocks the child once its 64 KB buffer fills, and the diagnostics that explain\n  // a failure (curl writes every one of them to stderr) are what the error needs.\n  const errP = (async function () {\n    const chunks = []\n    if (child.stderr) {\n      for await (const c of child.stderr) chunks.push(c)\n    }\n    return chunks\n  })()\n  const timeoutP = timerRef.timeout(timeoutMs).then(function () { return 'timeout' })\n  const doneP = child.done.then(function () { return 'done' })\n  const winner = await Promise.race([doneP, timeoutP])\n  if (winner === 'timeout') {\n    child.terminate()\n    await readP.catch(function () { return [] })\n    await errP.catch(function () { return [] })\n    throw new Error(exeName + ' timeout')\n  }\n  const chunks = await readP\n  const errChunks = await errP.catch(function () { return [] })\n  const outcome = await child.done\n  const decode = function (list) {\n    let total = 0\n    for (const c of list) total += c.byteLength\n    const bytes = new Uint8Array(total)\n    let off = 0\n    for (const c of list) { bytes.set(c, off); off += c.byteLength }\n    return new TextDecoder().decode(bytes)\n  }\n  const out = decode(chunks)\n  if (outcome.exitCode !== 0) {\n    const err = decode(errChunks).trim()\n    throw new Error(exeName + ' exit ' + outcome.exitCode + ': ' + (err || out